body:
Upon further investigation I've got a hacky workaround:

Doing a scene.iterate and setting frustumCulling to false, on all THREE.Mesh'es, after everything is loaded, rendering one frame ( renderer.render(scene,camera) )
and then doing scene.iterate and re-enabling frustumCulling on mesh objects,
makes these exceptions stop happening.
hth until this is fixed.

```
    scene.traverse(function(o){
        if(o instanceof THREE.Mesh && o.frustumCulled){
            o.frustumCulled = false;
            o.hadCullingEnabled = true;
        }
    });
    renderer.render(scene, camera);
    scene.traverse(function(o){
        if(o instanceof THREE.Mesh && o.hadCullingEnabled){
            o.frustumCulled = true;
            delete o.hadCullingEnabled;
        }
    });
```
